/// <summary>
/// MPJ_30715 Purchase Order Contract
/// </summary>
[DataContractAttribute]
public class METPurchaseOrderLineIntegrationStatusRequestContract extends METPurchaseOrderLineRequestContract
{
    METIntegrationStatus    integrationStatus = METIntegrationStatus::Acknowledged;    //default value
    Description             integrationStatusStr;

}

Method.Source:
    [DataMemberAttribute('integrationStatus')]
    public Description parmIntegrationStatusStr(Description _integrationStatusStr = integrationStatusStr)
    {
        integrationStatusStr = _integrationStatusStr;

        return integrationStatusStr;
    }

public METIntegrationStatus getIntegrationStatus()
{
    integrationStatus = str2Enum(integrationStatus, integrationStatusStr);
    
    if(enum2int(integrationStatus) == 255) //ie not a valid value
    {
        integrationStatus = METIntegrationStatus::None;
    }
    
    return integrationStatus;
}
